function hero(ar,en,subAr,subEn,{home=false,team=false,actions=true,crumb='',category=''}={}){return `<section class="hero ${home?'home-hero':''} ${team?'team-hero':''}"><div class="hero-photo" role="img" aria-label="${team?'Electrical engineers inspecting switchgear':'Industrial electrical switchgear'}"></div><div class="hero-red"></div><div class="container hero-inner"><div class="hero-copy">${!home?`<div class="breadcrumbs"><a href="index.html">${bi('الرئيسية','Home')}</a><span>‹</span>${crumb?`<a href="${page==='project'?'projects':'services'}.html">${crumb}</a><span>‹</span>`:''}<span>${bi(ar,en)}</span></div>`:''}<h1>${bi(ar,en)}</h1>${subAr?`<p class="hero-description">${bi(subAr,subEn)}</p>`:''}${category?`<div class="category-label">${icon('drop')}${category}</div>`:''}${actions?`<div class="hero-buttons">${button(home?'تواصل معنا':'اطلب عرض سعر',home?'Contact Us':'Request a Quote',home?'contact.html':'contact.html?inquiry=quote')}${button(home?'اكتشف خدماتنا':'تواصل معنا',home?'Explore Our Services':'Get in Touch',home?'services.html':'contact.html','outline-light')}</div>`:''}</div></div></section>`;}
